@import url('https://cdn.jsdelivr.net/npm/comic-mono@0.0.1/index.min.css');

@layer component {
  .code {
    white-space: pre-wrap;
    tab-size: 2;
    word-wrap: break-word;

    --sh-class: light-dark(var(--c-pink-800), var(--c-pink-300));
    --sh-identifier: light-dark(var(--c-deep-purple-800), var(--c-deep-purple-300));
    --sh-sign: light-dark(var(--c-blue-700), var(--c-blue-300));
    --sh-property: light-dark(var(--c-cyan-800), var(--c-cyan-300));
    --sh-entity: light-dark(var(--c-green-900), var(--c-green-200));
    --sh-jsxliterals: light-dark(var(--c-lime-800), var(--c-lime-300));
    --sh-string: light-dark(var(--c-amber-800), var(--c-amber-300));
    --sh-keyword: light-dark(var(--c-deep-orange-800), var(--c-deep-orange-300));
    --sh-comment: light-dark(var(--c-grey-700), var(--c-grey-400));

    &,
    & * {
      font-family: 'Comic Mono', ui-monospace, Consolas, monospace;
    }

    &.inline {
      padding: 0 0.25rem;
      line-height: 1;
    }
  }

  .inline,
  .codeWrapper {
    border-radius: var(--radius);
    background-color: color-mix(in oklch, color-mix(in oklch, var(--c-muted), var(--c-bg)), #0000 33%);
  }
  .codeWrapper {
    position: relative;
    border: 0.125rem solid var(--c-border);
    padding: 0.5rem 1rem;
    overflow: hidden;

    --copy-button-size: 2rem;

    &.hasButton {
      :global(.sh__line):last-child {
        padding-right: var(--copy-button-size);
      }
    }

    .copyButton {
      position: absolute;
      right: 0.5rem;
      bottom: min(0.5rem, calc(50% - var(--copy-button-size) / 2));
      width: var(--copy-button-size);
      height: var(--copy-button-size);
    }
  }
}

import { useCachedStyles } from '@/hook/useCachedStyles';
import { getCommonProps, type CommonProps } from '@/lib/utils';
import { Button } from '@/ui/button/button';
import { check, copy, Icon } from '@/ui/icon/icon';
import { useMemo, useState } from 'react';
import { highlight, type HighlightOptions } from 'sugar-high';
import classes from './code.module.css';

interface CodeProps {
  code: string;
  options?: HighlightOptions;
  noCopy?: boolean;
}
type BlockCodeProps = CommonProps<'pre', CodeProps & { inline?: false }>;
type InlineCodeProps = CommonProps<'code', CodeProps & { inline: true }>;

export function Code({ code, options, inline, noCopy, style, ...props }: BlockCodeProps | InlineCodeProps) {
  const [copied, setCopied] = useState(false);

  const cStyles = useCachedStyles(),
    allStyles = { ...cStyles, ...style };
  const highlighted = useMemo(() => highlight(code, options), [code, options]);

  if (inline)
    return (
      <code
        style={allStyles}
        {...getCommonProps(props, classes.code, classes.inline)}
        dangerouslySetInnerHTML={{ __html: highlighted }}
      />
    );

  return (
    <pre
      style={allStyles}
      // props is not really BlockCodeProps here, but this is short and valid enough
      {...getCommonProps(props as BlockCodeProps, classes.codeWrapper, !noCopy && classes.hasButton)}
    >
      <code className={classes.code} dangerouslySetInnerHTML={{ __html: highlighted }} />

      {noCopy || (
        <Button
          className={classes.copyButton}
          variant='muted'
          size='icon'
          onClick={async () => {
            await navigator.clipboard.writeText(code);
            setCopied(true);
            setTimeout(() => setCopied(false), 1000);
          }}
        >
          <Icon path={copied ? check : copy} />
        </Button>
      )}
    </pre>
  );
}
